# AI Office v1.8 Part C Dashboard, Certification, and Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v1.8-part-c-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $Backup = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $Backup
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $Backup -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
foreach ($Directory in @(
 "workspace\business-incubator\certification",
 "dashboard\runtime",
 "dashboard\public",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
Write-EmbeddedFile -RelativePath "config\business-incubator\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\New-AIOfficeBusinessIncubatorDashboardSnapshot.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\Certify-AIOfficeBusinessIncubator.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\Publish-AIOfficeBusinessIncubatorRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\Test-AIOfficeBusinessIncubator.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\business-incubator-module.js" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\business-incubator-module.css" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\Install-AIOfficeBusinessIncubatorDashboardIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\business-incubator\Test-AIOfficeBusinessIncubatorDashboard.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.8-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.8-Part-C-Dashboard-Certification-Release.md" -Base64Content ""
# Preserve the Part B PowerShell 5.1 repair in the stored installer if the bad syntax remains.
$PartBInstaller = "E:\AI\AI-Office\Installers\AI-Office-v1.8-Part-B-Validation-Venture-Planning-Install.ps1"
if (Test-Path -LiteralPath $PartBInstaller -PathType Leaf) {
 $PartBContent = Get-Content -LiteralPath $PartBInstaller -Raw
 $Bad = "Sort-Object score -Descending, name"
 $Good = "Sort-Object ``r``n        @{ Expression = { [double]`$_.score }; Descending = `$true },``r``n        @{ Expression = { [string]`$_.name }; Descending = `$false }"
 if ($PartBContent.Contains($Bad)) {
   $PartBContent = $PartBContent.Replace($Bad,$Good)
   Set-Content -LiteralPath $PartBInstaller -Value $PartBContent -Encoding UTF8
   Write-Host "[PATCHED] Part B installer PowerShell 5.1 portfolio sorting" -ForegroundColor Green
 }
}
$Scripts = Get-ChildItem -LiteralPath "E:\AI\AI-Office\scripts\business-incubator" -Filter "*.ps1" -File
foreach ($Script in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
& "E:\AI\AI-Office\scripts\business-incubator\New-AIOfficeBusinessIncubatorDashboardSnapshot.ps1" | Out-Null
Write-Host ""
Write-Host "AI Office v1.8 Part C Dashboard, Certification, and Release installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan